from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaObject, SchemaField


class PlanObjectV2(SchemaObject):
    className = SchemaField(name="className")
    distName = SchemaField(name="distName")
    version = SchemaField(name="version", optional=True)
    json_repr = SchemaField(name="payload", optional=True)

    def __init__(self, className, distName, json_repr, version):
        """
        :param className: NIDD class name of the object
        :param distName: NIDD dist name addr
        :param version: NIDD version
        :param json_repr: user plan id
        """
        self.className = className
        self.distName = distName
        self.version = version
        self.json_repr = json_repr

        super(PlanObjectV2, self).__init__()


